"""Max-size rule sets (2048 rules / 16384 positions) vs reference."""
import json, random, sys, os, tempfile
sys.path.insert(0, os.path.dirname(os.path.abspath(__file__)))
from ref import Ref
import fuzz

def gen_config(rnd):
    nr = rnd.choice([1, 37, 512, 2048])
    per = rnd.choice([1, 8, 32])
    while nr * per > 16384:
        per -= 1
    W = rnd.choice([1, 32])
    rules = []
    for i in range(nr):
        rr = []
        for _ in range(per):
            c = rnd.random()
            if c < 0.15:
                lo, hi = -2048, 2048
            elif c < 0.3:
                v = rnd.randint(-2048, 2048); lo, hi = v, v
            else:
                lo = rnd.randint(-2048, 2048); hi = rnd.randint(lo, 2048)
            rr.append([lo, hi])
        rules.append({"id": rnd.randrange(0, 2 ** 31), "class": rnd.randint(0, 65535),
                      "priority": rnd.randint(-2 ** 31, 2 ** 31 - 1), "ranges": rr})
    fb = {"class": rnd.randint(0, 65535)}
    for _ in range(rnd.randint(0, 4)):
        fb = {"feature": rnd.randrange(W), "threshold": rnd.randint(-2048, 2048),
              "le": fb, "gt": {"class": rnd.randint(0, 65535)}}
    return {"version": 1, "idle_timeout": rnd.choice([0, 3, 10 ** 9]),
            "packet_limit": rnd.choice([1, 4, 10 ** 9]), "prefix_width": W,
            "rules": rules, "fallback": fb}

def gen_requests(rnd, cfg):
    reqs = [{"op": "open", "flow": 1, "time": 0}, {"op": "open", "flow": 2, "time": 0}]
    t = 0
    npk = rnd.randint(40, 160)
    live = [1, 2]
    while npk > 0:
        t += rnd.choice([0, 0, 1, 2])
        n = min(rnd.randint(1, 6), npk)
        pk = []
        for _ in range(n):
            tt = t + rnd.randint(0, 1)
            pk.append({"flow": rnd.choice(live), "time": max(tt, t),
                       "source": rnd.randint(0, 1), "length": rnd.choice([1, 5, 100, 1024, 2048, rnd.randint(1, 2048)])})
        t = max(p["time"] for p in pk)
        npk -= n
        reqs.append({"op": "chunk", "packets": pk})
        if rnd.random() < 0.1:
            reqs.append({"op": "checkpoint"})
    reqs.append({"op": "checkpoint"})
    for f in live:
        t += 1
        reqs.append({"op": "close", "flow": f, "time": t})
    return reqs

for s in range(int(sys.argv[1]), int(sys.argv[1]) + int(sys.argv[2])):
    rnd = random.Random(s)
    cfg = gen_config(rnd); reqs = gen_requests(rnd, cfg)
    ref = Ref(cfg); exp = []; snaps = {}
    for i, r in enumerate(reqs):
        out = ref.handle(r)
        if "checkpoint" in out:
            snaps[i] = out["checkpoint"]; exp.append(None)
        else:
            exp.append(out)
    with tempfile.TemporaryDirectory(dir="/workspace/tmp") as d:
        prog = fuzz.compile_prog(cfg, d)
        a = fuzz.Stream(prog); got = []; mysnap = {}
        for i, r in enumerate(reqs):
            resp = a.send(r)
            if "checkpoint" in resp:
                mysnap[i] = resp["checkpoint"]; got.append(None)
            else:
                got.append(resp)
        assert a.close() == 0
        for i, r in enumerate(reqs):
            if exp[i] is not None:
                assert got[i] == exp[i], (s, i, json.dumps(r), json.dumps(got[i])[:300], json.dumps(exp[i])[:300])
        for i in list(mysnap)[:1]:
            b = fuzz.Stream(prog)
            assert b.send({"op": "restore", "checkpoint": mysnap[i]}) == {"events": []}
            for j in range(i + 1, len(reqs)):
                resp = b.send(reqs[j])
                if exp[j] is None:
                    assert set(resp) == {"checkpoint"}
                else:
                    assert resp == exp[j], (s, "restart", j)
            assert b.close() == 0
    print("ok", s, flush=True)
print("ALL PASS")
PYEOF
